		// CHASM tasks on transaction close.
		taskID := task.TaskID
		tgClock := backend.GetExecutionInfo().TaskGenerationShardClockTimestamp
		if tgClock != 0 && taskID != 0 && taskID < tgClock {
			return consts.ErrStaleReference
		}

		return nil
	}
}

// discardChasmSideEffectTask handles the discard of a CHASM side effect task on
// standby clusters, after the task has been pending past the configured discard
// delay.
//
// It first checks whether the execution still exists on the source (active)
// cluster; if it is gone, there is nothing to discard and nil is returned.
//
// If the execution still exists and the task's executor implements a custom
// discard handler (HasDiscardHandler() == true), the handler is invoked via
// tree.ExecuteSideEffectDiscardTask. Otherwise, a warning is logged and
// consts.ErrTaskDiscarded is returned.
func discardChasmSideEffectTask(
	ctx context.Context,
	engine chasm.Engine,
	registry *chasm.Registry,
	tree historyi.ChasmTree,
	task *tasks.ChasmTask,
	logger log.Logger,
	clusterName string,
	clientBean client.Bean,
	namespaceRegistry namespace.Registry,
) error {
	// (1) If the execution no longer exists on the source (active) cluster, then
	// the task was already executed (or the execution was deleted) there, and there
	// is nothing to discard.
	if !executionExistsOnSource(
		ctx,
		taskWorkflowKey(task),
		getTaskArchetypeID(task),
		logger,
		clusterName,
		clientBean,
		namespaceRegistry,
		registry,
	) {
		return nil
	}

	// (2) Look up the task type.
	registrableTask, ok := registry.TaskByID(task.Info.GetTypeId())
	if !ok {
		return serviceerror.NewInternalf("unknown task type id: %d", task.Info.GetTypeId())
	}

	// (3) No custom discard handler: fall back to silently discarding the task.
	if !registrableTask.HasDiscardHandler() {
		logger.Warn("Discarding standby CHASM side effect task due to task being pending for too long.", tag.Task(task))
