func newOutboundQueueActiveTaskExecutor(
	shardCtx historyi.ShardContext,
	workflowCache wcache.Cache,
	logger log.Logger,
	metricsHandler metrics.Handler,
	chasmEngine chasm.Engine,
) *outboundQueueActiveTaskExecutor {
